args.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Georgia', serif;
  overflow-x: hidden;
  background: #0a0a0a;
}

.parallax-container {
  position: relative;
  overflow: hidden;
}

.parallax-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  z-index: -1;
  will-change: transform;
}

.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: white;
  position: relative;
  padding: 2rem;
}

.hero-title {
  font-size: clamp(2.5rem, 8vw, 5rem);
  font-weight: 700;
  margin-bottom: 1rem;
  text-shadow: 3px 3px 8px rgba(0,0,0,0.8);
  animation: fadeInUp 1.2s ease-out;
}

.hero-subtitle {
  font-size: clamp(1rem, 3vw, 1.8rem);
  color: #ddd;
  margin-bottom: 2rem;
  animation: fadeInUp 1.4s ease-out;
}

.profile-img {
  width: clamp(180px, 30vw, 350px);
  height: clamp(180px, 30vw, 350px);
  border-radius: 50%;
  object-fit: cover;
  border: 6px solid rgba(255,255,255,0.2);
  box-shadow: 0 15px 50px rgba(0,0,0,0.6);
  margin-bottom: 2rem;
  animation: fadeInScale 1.6s ease-out;
  transition: transform 0.3s ease;
}

.profile-img:hover {
  transform: scale(1.05);
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeInScale {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.content-section {
  background: linear-gradient(to bottom, rgba(255,255,255,0.95), rgba(245,245,250,0.98));
  position: relative;
  z-index: 1;
  padding: 5rem 2rem;
  transform-style: preserve-3d;
}

.container {
  max-width: 1100px;
  margin: 0 auto;
}

.info-card {
  background: white;
  border-radius: 16px;
  padding: 3rem 2.5rem;
  margin-bottom: 3rem;
  box-shadow: 0 10px 40px rgba(0,0,0,0.12);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  opacity: 0;
  transform: translateY(50px);
}

.info-card.animate {
  opacity: 1;
  transform: translateY(0);
}

.info-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 60px rgba(0,0,0,0.18);
}

.info-card h2 {
  color: #16213e;
  font-size: clamp(1.8rem, 4vw, 2.5rem);
  margin-bottom: 1.5rem;
  border-bottom: 3px solid #0f3460;
  padding-bottom: 0.8rem;
}

.info-card p,
.info-card li {
  color: #333;
  font-size: clamp(1rem, 2.5vw, 1.15rem);
  line-height: 1.8;
  margin-bottom: 1rem;
}

.info-card ul {
  list-style: none;
  padding-left: 0;
}

.info-card li {
  padding-left: 2rem;
  position: relative;
  margin-bottom: 0.8rem;
}

.info-card li::before {
  content: "▪";
  position: absolute;
  left: 0.5rem;
  color: #0f3460;
  font-size: 1.3rem;
}

.parallax-layer {
  transition: transform 0.1s ease-out;
  will-change: transform;
}

@media (max-width: 768px) {
  .hero {
    min-height: 90vh;
  }

  .content-section {
    padding: 3rem 1rem;
  }

  .info-card {
    padding: 2rem 1.5rem;
  }
}

